### Python

```python
import sys

def main():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    x = list(map(int, input().split()))
    y = list(map(int, input().split()))

    y.sort()  # 对允许值集合排序
    INF = 10**18

    # dp[i][j] 表示前i个元素，第i个变为y[j]的最小操作次数
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0] = [0] * (m + 1)  # 前0个元素的边界情况

    for i in range(1, n + 1):
        prefix_min = INF
        for j in range(1, m + 1):
            # prefix_min 维护了 min_{1<=k<=j} dp[i-1][k]
            if dp[i-1][j] < prefix_min:
                prefix_min = dp[i-1][j]
            dp[i][j] = prefix_min + abs(x[i-1] - y[j-1])

    ans = min(dp[n][1:])  # 最后一个元素可以是任意y[j]
    print(ans)

if __name__ == "__main__":
    main()
```

